var EXTRA=[{"dot": "gray", "j": "Cartilage", "h": "Osteotomia del ginocchio in Inghilterra: uso in forte aumento in vent'anni, con grandi differenze fra regioni", "v": "Analisi dei dati amministrativi del servizio sanitario inglese su tibia e femore distale: l'uso cresce, ma l'accesso varia molto da regione a regione. Non dice nulla sugli esiti.", "pmid": "42982057", "doi": "10.1177/19476035261498345", "temi": ["osteotomia", "registro", "accesso alle cure"]}, {"dot": "gray", "j": "J Arthroplasty", "h": "Protesi monocompartimentale nei registri di più paesi: uso molto variabile, quasi ovunque sotto la soglia associata a esiti migliori", "v": "Analisi descrittiva dei rapporti annuali dei registri nazionali: mostra quanto poco la tecnica sia usata rispetto a quanti sarebbero eleggibili, non quali esiti abbia.", "pmid": "42982245", "doi": "10.1016/j.arth.2026.10.041", "temi": ["protesi monocompartimentale", "registro", "utilizzo"]}, {"dot": "gray", "j": "Knee", "h": "Protesi femoro-rotulea moderna con oltre dieci anni di controllo: la sopravvivenza cala con gli anni", "v": "Serie consecutiva senza gruppo di confronto: descrive la durata di un impianto, non dice se un'altra strategia durerebbe di più.", "pmid": "42987667", "doi": "10.1016/j.knee.2026.104664", "temi": ["protesi femoro-rotulea", "sopravvivenza", "follow-up lungo"]}, {"dot": "gray", "j": "J Exp Orthop", "h": "Pianificare la correzione solo sulla tibia porta spesso a un angolo tibiale mediale elevato", "v": "Studio radiografico su database con misura assistita da intelligenza artificiale: è un calcolo di pianificazione, non un esito clinico dell'osteotomia.", "pmid": "42985114", "doi": "10.1002/jeo2.70977", "temi": ["osteotomia tibiale", "pianificazione", "allineamento"]}, {"dot": "gray", "j": "Arthrosc Tech", "h": "Lesioni condrali a tutto spessore: nota tecnica sulla nanofrattura con guida curva", "v": "Descrizione di tecnica da un centro indiano: il valore è nella procedura descritta, non in un risultato clinico.", "pmid": "42979342", "doi": "10.1002/atn2.70320", "temi": ["cartilagine", "nanofrattura", "nota tecnica"]}, {"dot": "gray", "j": "Arthrosc Tech", "h": "LCA con tendini della zampa d'oca lasciati inseriti sulla tibia e tensione regolata a doppia puleggia", "v": "Nota tecnica cinese: descrive un modo di regolare la tensione dei fasci; non riporta confronti con altre tecniche nell'abstract.", "pmid": "42979281", "doi": "10.1002/atn2.70343", "temi": ["LCA", "innesto hamstring", "nota tecnica"]}, {"dot": "gray", "j": "Arthrosc Sports Med Rehabil", "h": "Rilascio del legamento collaterale mediale in artroscopia: la tecnica da fuori verso dentro è la più studiata", "v": "Revisione sistematica di studi eterogenei: dice quale tecnica ha più dati, e il titolo parla di evidenza superiore; l'abstract va letto come descrizione, non come confronto.", "pmid": "42979084", "doi": "10.1002/ars2.70087", "temi": ["collaterale mediale", "artroscopia", "revisione sistematica"]}, {"dot": "gray", "j": "Am J Sports Med", "h": "Legamento collaterale mediale profondo: carico a rottura e rigidità misurati su ginocchia di cadavere", "v": "Studio di laboratorio descrittivo: dà proprietà meccaniche della struttura, non indicazioni cliniche.", "pmid": "42975047", "doi": "10.1177/03635465261497503", "temi": ["collaterale mediale", "biomeccanica", "cadavere"]}, {"dot": "gray", "j": "J Exp Orthop", "h": "Tratti di personalità dopo lesione del LCA: studio di registro svedese", "v": "Studio trasversale: descrive associazioni con dati demografici e non misura il rientro allo sport né gli esiti.", "pmid": "42985230", "doi": "10.1002/jeo2.70967", "temi": ["LCA", "aspetti psicologici", "registro"]}, {"dot": "gray", "j": "KSSTA", "h": "Tasche di cemento sotto il piatto tibiale e meno revisioni per mobilizzazione asettica", "v": "Coorte monocentrica molto ampia: l'associazione è osservazionale e non prova che sia la tasca a ridurre le revisioni.", "pmid": "42975568", "doi": "10.1002/ksa.70642", "temi": ["protesi", "piatto tibiale", "mobilizzazione asettica"]}, {"dot": "gray", "j": "Ther Adv Musculoskelet Dis", "h": "Consensus Delphi sulla definizione di artrosi del ginocchio refrattaria", "v": "Revisione sistematica più Delphi: definisce chi non risponde a una terapia conservativa ottimizzata; non dà indicazioni chirurgiche.", "pmid": "42973704", "doi": "10.1177/1759720X261485403", "temi": ["artrosi", "consensus", "terapia conservativa"]}];

var SCOPERTE=[{"t": "Un modello al computer della cartilagine dopo trauma: perché il carico eccessivo e l'infiammazione degradano la matrice in tempi diversi", "v": "Ingegneria biomeccanica (Università della Finlandia orientale, Kuopio): un modello a elementi finiti riproduce la perdita di collagene e aggrecano in profondità, con l'infiammazione da carico che agisce in modo transitorio e quella da citochine in modo prolungato. Vale la deviazione per vedere come si ragiona sul danno post-traumatico; è un modello, nessun paziente.", "pmid": "42986911", "doi": "10.1371/journal.pcbi.1014935", "temi": ["bioingegneria", "cartilagine", "artrosi post-traumatica", "modello"]}, {"t": "Le app e i sensori per prevenire l'artrosi dopo un trauma del ginocchio: quanto coprono le raccomandazioni OPTIKNEE?", "v": "Revisione di scoping (Queen Mary University, Londra) delle soluzioni digitali messe a confronto con le sette raccomandazioni OPTIKNEE sulla prevenzione dell'artrosi post-traumatica. Interessa per il follow-up a distanza dopo LCA e menisco; è una mappa dell'esistente, non una prova di efficacia.", "pmid": "42980267", "doi": "10.2196/99607", "temi": ["salute digitale", "artrosi post-traumatica", "prevenzione", "follow-up"]}, {"t": "Una medicazione a infrarosso lontano nell'artrosi del ratto: segnali della via BMP-Smad nella cartilagine", "v": "Medicina sperimentale cinese (Accademia cinese delle scienze mediche tradizionali): in un modello di artrosi da sezione del LCA nel ratto, confronto con ialuronato e analisi trascrittomica. Preclinico: vale la deviazione per vedere un filone terapeutico asiatico, non per la pratica.", "pmid": "42988403", "doi": "10.12200/j.issn.1003-0034.20241180", "temi": ["medicina cinese", "artrosi", "preclinico", "cartilagine"]}];

var SOC={"1": {"video": "Quando si misura la rotazione della tibia sul femore con una risonanza magnetica, conta quanto il ginocchio è piegato durante l'esame? Uno studio di Londra ha guardato 310 risonanze di 106 calciatori professionisti con legamento crociato leso o operato.\n\nPiù il ginocchio era piegato durante l'esame, più la tibia sembrava ruotata verso l'interno. Una differenza di 10-20 gradi di flessione sposta la misura di circa 1,5-3 gradi. Pesava molto anche la differenza di inclinazione del piatto tibiale fra lato esterno e interno.\n\nIl limite: lo studio guarda indietro nel tempo, in giocatori professionisti, e misura la rotazione da fermi. Non dice nulla su stabilità, rotture o rientro. Il rinforzo laterale non risultava associato, ma non sappiamo in quanti casi era presente.\nFonte: PubMed, PMID 42982012.", "linkedin": "Rotazione tibio-femorale alla risonanza dopo lesione del legamento crociato: la flessione dell'esame conta. Uno studio di Londra su 310 risonanze di 106 calciatori professionisti.\n\nOgni grado in più di flessione si associa a 0,15° di rotazione interna apparente (IC 95% 0,02-0,27°). L'asimmetria di inclinazione del piatto tibiale è un predittore indipendente forte: 1,33° per grado (IC 95% 0,72-1,95°). Il rinforzo laterale non risultava associato (p = 0,328).\n\nIl limite: retrospettivo, solo calciatori professionisti, misura statica di imaging senza esiti clinici, numero di casi con rinforzo laterale non riportato.\nFonte: PubMed, PMID 42982012.", "instagram": "Risonanza del ginocchio e rotazione della tibia: conta quanto il ginocchio è piegato durante l'esame.\n\nSu 310 risonanze di calciatori professionisti, 10-20 gradi di flessione in più spostano la misura di circa 1,5-3 gradi.\n\nMisura statica, nessun esito clinico. PMID 42982012.", "pazienti": "Quando si fa una risonanza al ginocchio dopo una lesione del legamento crociato, si può misurare quanto la tibia è ruotata rispetto al femore. Uno studio di Londra su 310 risonanze di calciatori professionisti ha visto che il risultato dipende anche da quanto il ginocchio è piegato durante l'esame.\n\nUna differenza di 10-20 gradi di piegamento cambia la misura di circa 1,5-3 gradi. Conta anche l'inclinazione del piatto della tibia, che varia da una persona all'altra.\n\nLo studio misura solo un'immagine da fermi e non dice come va il ginocchio nella vita di ogni giorno: per questo i dati vanno letti con il proprio chirurgo, caso per caso.\nFonte: PubMed, PMID 42982012."}};

var SOCV={"1": {"video": {"chir": ["Rotazione tibio-femorale statica alla RM dopo LCA (The Knee, 2026): 310 RM di 106 calciatori professionisti, 106 ginocchia con LCA leso e 204 dopo ricostruzione, età media 23,3 anni.", "Più flessione durante l'acquisizione, più rotazione interna apparente: β 0,15° per grado (IC 95% 0,02-0,27°; p = 0,020). L'asimmetria di slope è un predittore indipendente: β 1,33° per grado (IC 95% 0,72-1,95°; p < 0,001), con interazione con la flessione (p = 0,008) e con lo stato del LCA (p = 0,019). LET p = 0,328.", "Il limite: retrospettivo, solo calciatori professionisti, misura di imaging senza esiti clinici, numero di LET non riportato (il p = 0,328 non prova l'assenza di effetto). Con 10-20° di differenza di flessione si spostano circa 1,5-3°: standardizzare la flessione.\nFonte: PubMed, PMID 42982012."], "misto": ["Quando si misura la rotazione della tibia sul femore con una risonanza magnetica, conta quanto il ginocchio è piegato durante l'esame? Uno studio di Londra ha guardato 310 risonanze di 106 calciatori professionisti con legamento crociato leso o operato.", "Più il ginocchio era piegato durante l'esame, più la tibia sembrava ruotata verso l'interno. Una differenza di 10-20 gradi di flessione sposta la misura di circa 1,5-3 gradi. Pesava molto anche la differenza di inclinazione del piatto tibiale fra lato esterno e interno.", "Il limite: lo studio guarda indietro nel tempo, in giocatori professionisti, e misura la rotazione da fermi. Non dice nulla su stabilità, rotture o rientro. Il rinforzo laterale non risultava associato, ma non sappiamo in quanti casi era presente.\nFonte: PubMed, PMID 42982012."], "pazienti": ["Quando si fa una risonanza al ginocchio dopo una lesione del legamento crociato, si può misurare quanto la tibia è ruotata rispetto al femore. Uno studio di Londra su 310 risonanze di calciatori professionisti ha visto che il risultato dipende anche da quanto il ginocchio è piegato durante l'esame.", "Una differenza di 10-20 gradi di piegamento cambia la misura di circa 1,5-3 gradi. Conta anche l'inclinazione del piatto della tibia, che varia da una persona all'altra.", "Lo studio misura solo un'immagine da fermi e non dice come va il ginocchio nella vita di ogni giorno: per questo i dati vanno letti con il proprio chirurgo, caso per caso.\nFonte: PubMed, PMID 42982012."]}, "linkedin": {"chir": ["Rotazione tibio-femorale statica a RM dopo LCA (The Knee, 2026): coorte retrospettiva di 310 RM in 106 calciatori professionisti (Fortius Clinic, Londra), 106 LCA lesi e 204 ricostruiti.", "Flessione durante l'esame β 0,15° per grado (IC 95% 0,02-0,27°; p = 0,020); asimmetria di slope β 1,33° per grado (IC 95% 0,72-1,95°; p < 0,001), interazione con flessione (p = 0,008) e stato del LCA (p = 0,019). LET p = 0,328; stato del LCA da solo p = 0,582.", "Il limite: retrospettivo, un solo gruppo, rotazione statica senza esiti funzionali, innesto e numero di LET non riportati. Implicazione di metodo: standardizzare la flessione, 10-20° valgono circa 1,5-3°.\nFonte: PubMed, PMID 42982012."], "misto": ["Rotazione tibio-femorale alla risonanza dopo lesione del legamento crociato: la flessione dell'esame conta. Uno studio di Londra su 310 risonanze di 106 calciatori professionisti.", "Ogni grado in più di flessione si associa a 0,15° di rotazione interna apparente (IC 95% 0,02-0,27°). L'asimmetria di inclinazione del piatto tibiale è un predittore indipendente forte: 1,33° per grado (IC 95% 0,72-1,95°). Il rinforzo laterale non risultava associato (p = 0,328).", "Il limite: retrospettivo, solo calciatori professionisti, misura statica di imaging senza esiti clinici, numero di casi con rinforzo laterale non riportato.\nFonte: PubMed, PMID 42982012."], "pazienti": ["Quando si fa una risonanza al ginocchio dopo una lesione del legamento crociato, si può misurare quanto la tibia è ruotata rispetto al femore. Uno studio di Londra su 310 risonanze di calciatori professionisti ha visto che il risultato dipende anche da quanto il ginocchio è piegato durante l'esame.", "Una differenza di 10-20 gradi di piegamento cambia la misura di circa 1,5-3 gradi. Conta anche l'inclinazione del piatto della tibia, che varia da una persona all'altra.", "Lo studio misura solo un'immagine da fermi e non dice come va il ginocchio nella vita di ogni giorno: per questo i dati vanno letti con il proprio chirurgo, caso per caso.\nFonte: PubMed, PMID 42982012."]}, "instagram": {"chir": ["RM e rotazione tibio-femorale dopo LCA: la flessione dell'esame sposta la misura.", "310 RM, 106 calciatori. Flessione β 0,15° per grado (IC 95% 0,02-0,27°); asimmetria di slope β 1,33° per grado (IC 95% 0,72-1,95°).", "Retrospettivo, misura statica. PMID 42982012."], "misto": ["Risonanza del ginocchio e rotazione della tibia: conta quanto il ginocchio è piegato.", "Su 310 risonanze di calciatori professionisti, 10-20 gradi di flessione in più spostano la misura di circa 1,5-3 gradi.", "Misura da fermi, nessun esito clinico. PMID 42982012."], "pazienti": ["Risonanza al ginocchio: conta come è piegato durante l'esame.", "Su 310 risonanze di calciatori, il piegamento cambia la misura della rotazione della tibia di circa 1,5-3 gradi.", "Studio su immagini da fermi. PMID 42982012."]}, "reel": {"chir": ["[Rotazione TF alla RM dopo LCA]", "Flessione β 0,15° per grado; asimmetria di slope β 1,33° per grado (IC 95% 0,72-1,95°).", "Retrospettivo, statico. PMID 42982012."], "misto": ["[RM e rotazione della tibia]", "Piegare di più il ginocchio durante l'esame sposta la misura: 10-20 gradi valgono circa 1,5-3 gradi.", "Misura da fermi. PMID 42982012."], "pazienti": ["[Risonanza al ginocchio e piegamento]", "Come è piegato il ginocchio durante l'esame cambia la misura della rotazione della tibia.", "Studio su immagini. PMID 42982012."]}}};

var TAGS={"1": {"linkedin": "#Ortopedia #LegamentoCrociato #ChirurgiaDelGinocchio", "instagram": "#ortopedia #ginocchio #legamentocrociato #lca #risonanzamagnetica #calciatori #medicinadellosport #chirurgiadelginocchio #medicinabasatasulleprove #ortopediaticino #ticino", "kw": "legamento crociato anteriore, risonanza magnetica ginocchio, rotazione della tibia, pendenza del piatto tibiale, calciatori professionisti, ginocchio operato"}};

var NLB={"1": {"prof": ["RM e rotazione tibio-femorale dopo LCA: la flessione dell'esame sposta la misura", "Coorte retrospettiva (The Knee, 2026; solo abstract): 310 RM di 106 calciatori professionisti con LCA leso o ricostruito. Flessione durante l'esame β 0,15° per grado (IC 95% 0,02-0,27°; p = 0,020); asimmetria di slope β 1,33° per grado (IC 95% 0,72-1,95°; p < 0,001). LET p = 0,328.", "Nota critica: retrospettivo, solo calciatori professionisti, misura statica senza esiti clinici, numero di LET e innesto non riportati; il p = 0,328 non prova l'assenza di effetto."], "mix": ["Risonanza del ginocchio dopo il crociato: conta quanto il ginocchio è piegato durante l'esame", "Uno studio di Londra su 310 risonanze di 106 calciatori professionisti ha visto che la rotazione della tibia sul femore dipende da quanto il ginocchio è piegato durante l'esame e dall'inclinazione del piatto tibiale. Una differenza di 10-20 gradi di piegamento sposta la misura di circa 1,5-3 gradi.", "Nota sul limite: lo studio guarda indietro nel tempo, misura la rotazione da fermi e non dice nulla su stabilità, rotture o rientro allo sport."], "paz": ["Risonanza al ginocchio: il piegamento durante l'esame cambia la misura", "Dopo una lesione del legamento crociato si può misurare con la risonanza quanto la tibia è ruotata. In uno studio su 310 risonanze di calciatori professionisti, la misura cambiava di circa 1,5-3 gradi se il ginocchio era piegato di 10-20 gradi in più o in meno.", "Nota rassicurante: è una misura da fermi e non descrive come funziona il ginocchio; ogni caso va valutato dal proprio chirurgo."], "kw": "risonanza magnetica ginocchio, legamento crociato, rotazione tibia, calciatori, ginocchio operato"}, "2": {"prof": ["Monocompartimentale: sopravvivenza senza revisione 92% a 10 e 85% a 15 anni in 2.234 ginocchia", "Coorte retrospettiva monocentrica (JBJS Am, 2026; Mayo Clinic; livello III; solo abstract): 2.234 protesi monocompartimentali primarie 2000-2021. Sopravvivenza senza revisione 92% a 10 anni e 85% a 15; 118 revisioni, 97% convertite a protesi totale. HR univariate: tecnologia 0,4, alto volume 0,5, piatto mobile 1,9 (p < 0,01; IC non riportati).", "Nota critica: monocentrico, associazioni univariate senza intervalli, tecnologia soprattutto fluoroscopica (43% dei casi su un 59% con assistenza), possibile confondimento per epoca."], "mix": ["Protesi monocompartimentale del ginocchio: durata a 10 e 15 anni in un grande centro", "Uno studio della Mayo Clinic su 2.234 protesi che sostituiscono una sola parte del ginocchio ha visto che circa 92 su 100 non erano state revisionate dopo 10 anni e 85 su 100 dopo 15. La causa più frequente di revisione era la comparsa dell'artrosi nella parte vicina del ginocchio.", "Nota sul limite: un solo centro, guardando indietro nel tempo; le differenze fra tecniche non tengono conto di tutto ciò che è cambiato negli anni."], "paz": ["Protesi che sostituisce una parte del ginocchio: come va dopo 10 e 15 anni", "In uno studio su 2.234 protesi che sostituiscono solo una parte del ginocchio, circa 92 su 100 non erano state riviste dopo 10 anni e 85 su 100 dopo 15. Quando serviva una nuova operazione, quasi sempre si passava a una protesi totale.", "Nota rassicurante: i numeri vengono da un solo grande centro e non valgono per ogni caso; la scelta dell'intervento si discute con il proprio chirurgo."], "kw": "protesi monocompartimentale ginocchio, durata protesi ginocchio, revisione protesi, artrosi ginocchio"}, "3": {"prof": ["Osteotomia femorale distale per valgo: JLCA a 12 mesi, variabilità ampia nel singolo ginocchio", "Coorte retrospettiva monocentrica (J Exp Orthop, 2026; livello III; solo abstract): 62 ginocchia valghe, osteotomia di chiusura mediale. JLCA da −1,13 ± 2,04° a −0,56 ± 1,61°; cambiamento 0,57 ± 1,90° (intervallo da −4,6° a 6,9°). Valore preoperatorio coefficiente −0,56 (IC 95% da −0,78 a −0,34).", "Nota critica: 62 ginocchia, esplorativo, accoppiamento matematico, affidabilità radiografica non valutata, nessuna validazione esterna."], "mix": ["Osteotomia del femore per ginocchio a X: l'inclinazione dell'articolazione cambia poco, ma non per tutti", "In 62 ginocchia a X operate in Giappone con un'osteotomia del femore, l'inclinazione della linea dell'articolazione cambiava in media di circa mezzo grado a un anno, ma in singoli ginocchia fino a diversi gradi in più o in meno.", "Nota sul limite: pochi casi, un solo centro e un modello di previsione ancora esplorativo."], "paz": ["Ginocchio a X: dopo l'osteotomia del femore l'articolazione si assesta in modo diverso da persona a persona", "In uno studio su 62 ginocchia a X operate con un'osteotomia del femore, la linea dell'articolazione cambiava in media di poco a un anno, ma non allo stesso modo in tutti.", "Nota rassicurante: sono misure sulle radiografie e non dicono come stanno i pazienti; ogni piano di correzione è valutato dal proprio chirurgo."], "kw": "osteotomia femore distale, ginocchio valgo, ginocchio a X, correzione asse ginocchio"}, "4": {"prof": ["Allograft per gli stabilizzatori mediali della rotula: rassegna narrativa senza dati quantitativi", "Revisione narrativa (Sports Med Arthrosc Rev, 2026; solo abstract) sull'allograft per MPFL, MQTFL e MPTL in adulti e immaturi: risultati riferiti dai pazienti descritti come paragonabili all'autoinnesto e recidive simili o modestamente inferiori. Nessun numero nell'abstract.", "Nota critica: narrativa, nessuna strategia di ricerca dichiarata, giudizi degli autori che rinviano le raccomandazioni a studi prospettici."], "mix": ["Instabilità della rotula: la ricostruzione con tessuto da donatore secondo una rassegna", "Una rassegna di due autori descrive l'uso di tessuto da donatore per ricostruire i legamenti che trattengono la rotula, in adulti e in ragazzi ancora in crescita, e lo giudica sicuro e con risultati simili all'uso del proprio tendine.", "Nota sul limite: è una rassegna senza numeri nell'abstract e gli stessi autori chiedono studi più lunghi."], "paz": ["Rotula che si lussa: la rassegna sul tessuto da donatore per ricostruire i legamenti", "Una rassegna descrive la ricostruzione dei legamenti che trattengono la rotula usando tessuto da donatore invece del proprio tendine, in adulti e ragazzi in crescita.", "Nota rassicurante: non ci sono numeri e gli autori chiedono altri studi; la tecnica più adatta la sceglie il chirurgo caso per caso."], "kw": "lussazione rotula, ricostruzione MPFL, instabilità rotulea, legamento patello-femorale mediale"}, "5": {"prof": ["Dopo LCA, salto singolo e triplo prevedono la forza isocinetica a 6-8 mesi (R² 0,26-0,52)", "Studio trasversale (Sports Health, 2026; livello 3; solo abstract): 51 uomini a 6-8 mesi dalla ricostruzione. Regressione lineare semplice, R² aggiustato 0,26-0,52 (p < 0,001); LSI ≥85% come soglia. Triplo LSI correlato con estensione a 60°/s (p = 0,01).", "Nota critica: 51 uomini, una sola misura, nessun esito duro, innesto non riportato, molti confronti senza correzione dichiarata."], "mix": ["Dopo il crociato, i salti su una gamba dicono qualcosa sulla forza del muscolo a 6-8 mesi", "In 51 uomini operati al legamento crociato, la distanza di alcuni salti su una gamba prevedeva in parte la forza di estensione e flessione del ginocchio misurata con il dinamometro.", "Nota sul limite: una sola misura nel tempo e nessun dato su rientro allo sport o nuove rotture."], "paz": ["Dopo il legamento crociato: i salti su una gamba e la forza del ginocchio", "In uno studio su 51 uomini operati, la distanza dei salti su una gamba riusciva in parte a indicare la forza dei muscoli del ginocchio a 6-8 mesi dall'intervento.", "Nota rassicurante: non dice quando si può tornare allo sport; la decisione si prende con il chirurgo e il fisioterapista."], "kw": "legamento crociato, salti, forza quadricipite, recupero dopo crociato"}};

var ARTICLES=[{n:1,mono:'m-gray',dot:'green',sec:'res',j:'The Knee',h:'Rotazione tibio-femorale alla RM dopo LCA: la flessione dell\'esame e l\'asimmetria di slope spostano la misura',v:'Coorte retrospettiva di calciatori professionisti (Fortius Clinic, Londra): su 310 RM di 106 giocatori con LCA leso o ricostruito, più flessione durante l\'esame significa più rotazione interna apparente (β 0,15° per grado; IC 95% 0,02-0,27°; p = 0,020). L\'asimmetria di slope è un predittore indipendente forte (β 1,33° per grado; IC 95% 0,72-1,95°; p < 0,001). Il LET non risulta associato (p = 0,328).',ax:'Ackermann, Jones, Ball, Kabeer, Bamania, Watura, Lee, Williams',date:'nov 2026',meta:'coorte retrospettiva, 310 RM in 106 calciatori professionisti, solo abstract',pmid:'42982012',doi:'10.1016/j.knee.2026.104662',journal:'The Knee',authors:'Ackermann J, Jones M, Ball SV, Kabeer AS, Bamania P, Watura C, Lee JC, Williams A',design:'Revisione retrospettiva di calciatori professionisti sottoposti a ricostruzione primaria del LCA tra il 2012 e il 2024 con RM disponibile (Fortius Clinic e FIFA Medical Centre of Excellence, Londra; radiologia del Chelsea and Westminster). Rotazione tibio-femorale statica, slope mediale e laterale e flessione misurati sulla RM; asimmetria di slope (ΔPTS) definita come slope laterale meno mediale. Modelli lineari misti con interazioni per flessione, ΔPTS, stato del LCA (leso o ricostruito) e LET, aggiustati per lo stato meniscale. Solo abstract. Innesto, tecnica del LET, intervallo tra trauma e RM e livello di evidenza non riportati.',pop:'310 esami RM di 106 calciatori professionisti (età media 23,3 ± 4,2 anni): 106 con LCA leso e 204 dopo ricostruzione. Numero di casi con LET, sesso, innesto e follow-up: non riportati nell\'abstract.',results:'Più flessione durante l\'esame, più rotazione interna apparente: β 0,15° per grado di flessione (IC 95% 0,02-0,27°; p = 0,020). L\'asimmetria di slope è un predittore indipendente forte: β 1,33° per grado di ΔPTS (IC 95% 0,72-1,95°; p < 0,001), con interazione flessione × ΔPTS (p = 0,008; effetto maggiore vicino all\'estensione) e stato del LCA × ΔPTS (p = 0,019; più forte nel ginocchio senza LCA, attenuato dopo ricostruzione). Stato del LCA da solo p = 0,582; LET p = 0,328; variabili meniscali non associate in modo indipendente. Secondo il modello, 10-20° di differenza di flessione tra esami producono circa 1,5-3° di rotazione apparente.',concl:'Gli autori: la flessione durante l\'acquisizione influenza la rotazione assiale misurata; l\'asimmetria di slope resta un determinante indipendente dell\'allineamento rotazionale, con effetto minore a flessione maggiore e dopo ricostruzione; negli studi di rotazione statica a RM la flessione va standardizzata.',limits:'Retrospettivo, calciatori professionisti soltanto · La rotazione statica a RM è una misura di imaging, non di stabilità funzionale: nessun esito clinico (rottura, pivot shift, rientro) · Il LET non risulta associato (p = 0,328), ma l\'abstract non dice in quanti casi fosse presente: non è prova di assenza di effetto · Innesto, intervallo trauma-RM e tipo di LET non riportati',perte:'Verde: tocca slope e LET, i due fili della tua pratica, ma misura un parametro di imaging, non un esito. Gruppo Fortius (Andy Williams), nella tua rete. Due cose utili se leggi RM post-operatorie: la flessione dell\'esame sposta la misura di circa 1,5-3° ogni 10-20°, quindi confronti fra RM a flessioni diverse non valgono, e l\'asimmetria di slope pesa sulla rotazione soprattutto vicino all\'estensione e nel ginocchio senza LCA. Il LET non risulta associato alla rotazione statica, ma senza il numero di casi il dato è muto. Cosa fare: nessun cambio di indicazione; se confronti RM nel tempo, registra o standardizza la flessione, e guarda l\'asimmetria di slope oltre alla pendenza assoluta.'},
{n:2,mono:'m-gray',dot:'green',sec:'res',j:'JBJS Am',h:'Protesi monocompartimentale: sopravvivenza senza revisione 92% a 10 anni e 85% a 15 anni in 2.234 ginocchia',v:'Coorte consecutiva monocentrica (Mayo Clinic, 2000-2021, livello III): 118 revisioni su 2.234 protesi monocompartimentali, quasi tutte convertite a protesi totale. Nell\'analisi univariata meno revisioni con tecnologia di assistenza (HR 0,4; p < 0,01) e alto volume del chirurgo (HR 0,5; p < 0,01), più revisioni con il piatto mobile (HR 1,9; p < 0,01). La «tecnologia» è per oltre due terzi fluoroscopia, non robot.',ax:'Tsukamoto, MacInnis, Grimm, Bedard, Sierra, Pagnano, Abdel, Hannon',date:'nov 2026',meta:'coorte retrospettiva consecutiva monocentrica, 2.234 ginocchia, livello III, solo abstract',pmid:'42987190',doi:'10.2106/JBJS.26.00507',journal:'The Journal of bone and joint surgery. American volume',authors:'Tsukamoto I, MacInnis BR, Grimm JA, Bedard NA, Sierra RJ, Pagnano MW, Abdel MP, Hannon CP',design:'Coorte retrospettiva di protesi monocompartimentali primarie consecutive eseguite dal 2000 al 2021 in un unico centro accademico terziario (Mayo Clinic, Rochester); livello III dichiarato. Sopravvivenza senza revisione con Kaplan-Meier, fattori di rischio con regressione di Cox, esiti clinici con Knee Society Score. Solo abstract; follow-up mediano non riportato.',pop:'2.234 protesi monocompartimentali primarie: età media 65 anni, BMI medio 31 kg/m², donne 49%, pazienti bianchi 97%. Impianto a piatto fisso nel 78%. Tecnologia di assistenza nel 59% (fluoroscopia 43%, robotica 15%, navigazione 1%).',results:'Sopravvivenza senza revisione 92% a 10 anni e 85% a 15 anni (circa 1% di rischio annuo; intervalli di confidenza non riportati nell\'abstract). 118 protesi revisionate, il 97% con conversione a protesi totale; cause principali progressione dell\'artrosi nel compartimento adiacente (41%), mobilizzazione asettica (23%), dolore non spiegato (9%), problema dell\'impianto (9%). Analisi univariata: tecnologia di assistenza HR 0,4 (p < 0,01), alto volume del chirurgo HR 0,5 (p < 0,01), piatto mobile HR 1,9 (p < 0,01); intervalli non riportati. Knee Society Score da 47 prima dell\'intervento a 75 a cinque anni (p < 0,001).',concl:'Gli autori: sopravvivenza a lungo termine eccellente (circa 1% di revisione annua fino a 15 anni); tecnologia di assistenza, piatto fisso e alto volume del chirurgo associati a minor rischio di revisione.',limits:'Retrospettivo e monocentrico, popolazione quasi tutta bianca e con BMI medio 31 · Le associazioni riportate nell\'abstract sono univariate e senza intervalli di confidenza · Tecnologia e piatto fisso sono entrati nella pratica in epoche diverse nell\'arco 2000-2021: possibile confondimento per epoca (mio rilievo) · «Tecnologia di assistenza» è per oltre due terzi fluoroscopia, solo il 15% robotica: non dice nulla sul robot in sé',perte:'Verde: protesi, ma monocompartimentale, non la totale robotica (VELYS) che segui. Utile come riferimento di durata: 85% senza revisione a 15 anni in un centro ad alto volume, con l\'artrosi del compartimento adiacente come causa più frequente di fallimento. Non permette di dire che il robot riduca le revisioni, perché la tecnologia dello studio è soprattutto fluoroscopica. Cosa fare: nessun cambio; se discuti una monocompartimentale con un paziente, il dato è un riferimento di centro, non una promessa di durata.'},
{n:3,mono:'m-gray',dot:'green',sec:'res',j:'J Exp Orthop',h:'Osteotomia femorale distale di chiusura mediale: la convergenza della linea articolare cambia in media di 0,57° a 12 mesi, ma da −4,6° a +6,9° nel singolo ginocchio',v:'Coorte retrospettiva monocentrica giapponese (Kameda, livello III) su 62 ginocchia valghe: l\'angolo di convergenza della linea articolare passa da −1,13 ± 2,04° a −0,56 ± 1,61° a 12 mesi. Il valore preoperatorio è il predittore più forte del cambiamento (coefficiente −0,56; IC 95% da −0,78 a −0,34), ma il modello, con errore medio assoluto di 1,10°, resta esplorativo.',ax:'Kato, Ichikawa, Matsui, Takazawa, Koga, Yamada, Kiuchi, Ryu, Ohuchi',date:'nov 2026',meta:'coorte retrospettiva monocentrica, 62 ginocchia, livello III, solo abstract',pmid:'42979506',doi:'10.1002/jeo2.70975',journal:'Journal of experimental orthopaedics',authors:'Kato Y, Ichikawa K, Matsui H, Takazawa S, Koga S, Yamada S, Kiuchi A, Ryu A, Ohuchi H',design:'Coorte retrospettiva monocentrica (Kameda Medical Center, Chiba), ginocchia valghe trattate con osteotomia femorale distale di chiusura mediale tra ottobre 2017 e dicembre 2024, senza osteotomia aggiuntiva né ricostruzione legamentosa. Esito primario il cambiamento con segno dell\'angolo di convergenza della linea articolare (JLCA) a 12 mesi su radiografie sotto carico dell\'arto intero. Regressione lineare multivariabile (JLCA preoperatorio, mLDFA, mMPTA, età, sesso, BMI) con errori standard robusti per cluster e validazione incrociata interna. Solo abstract.',pop:'62 ginocchia (8 pazienti bilaterali). Età, sesso, BMI e entità della correzione: non riportati nell\'abstract.',results:'JLCA preoperatorio −1,13 ± 2,04° e a 12 mesi −0,56 ± 1,61°; cambiamento medio 0,57 ± 1,90° (mediana 0,3°; intervallo da −4,6° a 6,9°). Il JLCA preoperatorio è l\'associazione più forte con il cambiamento (coefficiente −0,56; IC 95% da −0,78 a −0,34; p < 0,001); anche mMPTA è associato in modo indipendente, mentre mLDFA, età, sesso e BMI no. R² 0,602 nel modello primario e 0,474 in validazione incrociata; errore quadratico medio 1,36° e assoluto 1,10°.',concl:'Gli autori: cambiamento medio piccolo ma variabilità tra ginocchia sostanziale; l\'associazione con il valore preoperatorio va letta con cautela per accoppiamento matematico; modello esplorativo, non uno strumento preciso per il singolo paziente; servono validazione esterna e affidabilità radiografica formale prima dell\'uso clinico.',limits:'62 ginocchia, un solo centro, retrospettivo e dichiaratamente esplorativo · Accoppiamento matematico: il JLCA preoperatorio compare sia nel predittore sia nella differenza che si vuole spiegare (lo dichiarano gli autori) · Affidabilità delle misure radiografiche non valutata formalmente · Nessun esito clinico, nessuna validazione esterna',perte:'Verde: osteotomia correttiva, filo della tua pratica, anche se qui è il femore distale per il valgo e non la tibia. Il messaggio utile alla pianificazione: dopo l\'osteotomia la linea articolare si muove poco in media (circa mezzo grado), ma nel singolo ginocchio può spostarsi di diversi gradi in entrambe le direzioni, e il modello non è abbastanza preciso da correggere il piano su un paziente. Cosa fare: nessun cambio di indicazione; nella pianificazione di un\'osteotomia non contare su una previsione individuale del JLCA e verifica la linea articolare sulla radiografia di controllo.'},
{n:4,mono:'m-gray',dot:'green',sec:'res',j:'Sports Med Arthrosc Rev',h:'Ricostruzione degli stabilizzatori mediali della rotula con allograft: rassegna narrativa, risultati descritti come paragonabili all\'autoinnesto',v:'Rassegna narrativa (Maffulli, Migliorini) su MPFL, MQTFL e legamento patello-tibiale mediale ricostruiti con allograft, in adulti e in pazienti scheletricamente immaturi: gli autori concludono che è sicura ed efficace, con risultati riferiti dai pazienti simili all\'autoinnesto e rotture recidive simili o un poco inferiori in alcune serie. Nessun numero nell\'abstract; confronti prospettici a lungo termine ancora necessari.',ax:'Maffulli, Migliorini',date:'nov 2026',meta:'revisione narrativa, nessun numero nell\'abstract, solo abstract',pmid:'42972656',doi:'10.1097/JSA.0000000000000488',journal:'Sports medicine and arthroscopy review',authors:'Maffulli N, Migliorini F',design:'Revisione narrativa dell\'evidenza sull\'allograft per la ricostruzione del legamento patello-femorale mediale (MPFL), del legamento quadricipite-femorale mediale (MQTFL) e del legamento patello-tibiale mediale (MPTL), da soli o combinati, in adulti e scheletricamente immaturi. Esiti clinici, esiti riferiti dai pazienti, complicanze, scelta dell\'innesto, tecnica e specificità pediatriche. Metodo di ricerca e numero di studi non riportati nell\'abstract.',pop:'Non riportata nell\'abstract (revisione narrativa); adulti e pazienti scheletricamente immaturi.',results:'Nessun risultato quantificato nell\'abstract. Dimensioni dell\'effetto e intervalli di confidenza non riportati nell\'abstract.',concl:'Gli autori: la ricostruzione con allograft degli stabilizzatori mediali è sicura ed efficace; esiti riferiti dai pazienti paragonabili all\'autoinnesto, recidive di lussazione simili o modestamente inferiori in diverse serie; negli immaturi permette fissazioni che risparmiano la fisi e senza mezzi di sintesi; la combinazione MPFL più MQTFL è una tecnica emergente; servono studi prospettici comparativi con follow-up più lungo prima di raccomandazioni definitive.',limits:'Narrativa: nessuna strategia di ricerca, nessun conteggio di studi e nessun numero nell\'abstract · «Paragonabili» e «modestamente inferiori» sono giudizi degli autori, non risultati misurati · Serie in gran parte non comparative; gli stessi autori rinviano le raccomandazioni · Nessun dato sulla scelta tra allograft e autoinnesto in rapporto alla tua tecnica',perte:'Verde: MPFL è nel tuo elenco di temi. Ma è una rassegna narrativa senza numeri nell\'abstract, e le conclusioni rassicuranti sono degli autori, che chiedono essi stessi studi prospettici. Cosa fare: nessun cambio; la rassegna serve come mappa delle tecniche (MPFL, MQTFL, MPTL, immaturi), non come prova che l\'allograft sia pari o superiore all\'autoinnesto.'},
{n:5,mono:'m-gray',dot:'gray',sec:'res',j:'Sports Health',h:'Dopo LCA, i salti monopodalici prevedono la forza isocinetica a 6-8 mesi: R² aggiustato da 0,26 a 0,52',v:'Studio trasversale (Turchia, livello 3) su 51 uomini a 6-8 mesi dalla ricostruzione: la distanza del salto singolo e del triplo mediale predice la forza isocinetica di estensione e flessione (R² aggiustato 0,26-0,52; p < 0,001). Gli autori lo propongono come complemento alla misura isocinetica; innesto e rirotture non riportati.',ax:'Kırık, Akdemir, Karaduman, Güzel, Genç, Anıl, Korkmaz Salkılıç, Kehribar, Önder, Yılmaz',date:'nov 2026',meta:'studio trasversale, 51 uomini, livello 3, solo abstract',pmid:'42981220',doi:'10.1177/19417381261486269',journal:'Sports health',authors:'Kırık ABT, Akdemir E, Karaduman E, Güzel N, Genç AS, Anıl B, Korkmaz Salkılıç E, Kehribar L, Önder Y, Yılmaz AK',design:'Studio trasversale (Dokuz Eylül University, Izmir, e Ondokuz Mayıs University, Samsun), livello 3 dichiarato. A 6-8 mesi dalla ricostruzione, forza isocinetica di estensione e flessione a 60, 180 e 240°/s e cinque test di salto monopodalico, con indice di simmetria degli arti (LSI) soglia ≥85%. Test t appaiati, correlazioni di Pearson, test di Fisher e regressione lineare semplice. Solo abstract; innesto e tecnica non riportati.',pop:'51 uomini con ricostruzione unilaterale del LCA, valutati a 6-8 mesi. Età, innesto, lesioni associate e follow-up successivo: non riportati nell\'abstract.',results:'Forza isocinetica, salto singolo, salto incrociato e triplo mediale non differiscono fra gli arti (p > 0,05), mentre la distanza del triplo (sigla TH, usata dall\'abstract in entrambe le frasi) e del salto con rotazione mediale a 90° è minore sul lato operato (p < 0,05). Lysholm e IKDC migliorano (p < 0,001), il Tegner no. Correlazione alta fra estensione a 60°/s e distanza del salto singolo e del triplo; la regressione lineare semplice dà R² aggiustato 0,26-0,52 (p < 0,001). Tra i valori LSI solo l\'estensione a 60°/s e il triplo LSI sono correlati (p = 0,01); coefficienti di correlazione non riportati nell\'abstract.',concl:'Gli autori: il salto singolo e il triplo sono predittori molto buoni della forza isocinetica dopo ricostruzione; possono essere un complemento pratico e accessibile alla misura isocinetica.',limits:'Trasversale, 51 uomini, una sola misura a 6-8 mesi: nessun dato su rottura successiva o rientro allo sport · Un R² di 0,26-0,52 lascia gran parte della variabilità della forza non spiegata dal salto · Solo uomini; innesto, lesioni associate e riabilitazione non riportati · Sono stati fatti molti confronti (cinque salti, tre velocità) senza correzione dichiarata nell\'abstract',perte:'Grigio: tocca il criterio di rientro (tensione 4), ma sostituisce un test con un altro entrambi intermedi, a 6-8 mesi, senza esito duro. Non dice che il salto soddisfi il criterio di rientro su innesto quadricipitale. Cosa fare: nessun cambio; se il dinamometro non è disponibile, il salto singolo e il triplo danno una stima grossolana della forza, non un permesso al rientro.'}];

var SUGGQ=[{"k": "kol", "n": "Christoph Kittl (Università di Münster, Germania)", "w": "Germania: ultimo autore dello studio sul carico del LCA con varismo e angolo posterolaterale (PMID 42897444; nome e afferenza letti nei metadati PubMed), già comparso in elenchi di coautori nello storico. Corrispondenza tecnica con l'osteotomia correttiva e la protezione del LCA con la ricostruzione dell'angolo posterolaterale, cioè gli ambiti osteotomia e slope che esegui. Sostituisce Daniel B. F. Saris (nessun segnale dell'utente arrivato per farla ruotare)."}];
var BRIEF_TEXT="Venerdì sei novembre, cinque lavori, nessuna scheda rossa o arancione. Il briefing di ieri è saltato perché la ricerca su PubMed non rispondeva: oggi la ricerca funziona e copre dal tre novembre. Nessun richiamo di dispositivi nuovo, nessuna ritrattazione che ti riguardi e nessun citante nuovo sui tuoi verdetti passati; il raccoglitore è quello di ieri mattina, ma la fonte delle linee guida non ha risposto e l'ho sostituita con una ricerca diretta: nessun consensus nuovo sul ginocchio operato, solo la definizione Delphi di artrosi refrattaria. Il lavoro del giorno viene dalla Fortius Clinic di Londra, nella tua rete. Trecentodieci risonanze di centosei calciatori professionisti con crociato leso o ricostruito: più il ginocchio è piegato durante l'esame, più la tibia sembra ruotata verso l'interno, zero virgola quindici gradi per grado di flessione, intervallo da zero virgola zero due a zero virgola ventisette. L'asimmetria di slope pesa molto di più, uno virgola trentatré gradi per grado, e il rinforzo laterale non risulta associato, ma l'abstract non dice in quanti casi c'era. Con dieci o venti gradi di flessione in più si sposta la misura di circa uno virgola cinque o tre gradi: nessun cambio d'indicazione, ma le risonanze vanno confrontate alla stessa flessione. Seconda scheda, la protesi monocompartimentale della Mayo Clinic: duemiladuecentotrentaquattro ginocchia, senza revisione il novantadue per cento a dieci anni e l'ottantacinque a quindici. Tecnologia e alto volume associati a meno revisioni, ma in analisi univariata, e la tecnologia è per lo più fluoroscopia, non robot. Terza, l'osteotomia femorale distale per il valgo: sessantadue ginocchia, la linea articolare cambia in media di zero virgola cinquantasette gradi ma da meno quattro virgola sei a più sei virgola nove nel singolo. Quarta, la rassegna narrativa sull'allograft per l'instabilità rotulea, senza numeri. Quinta, i salti monopodalici dopo il crociato come stima della forza a sei otto mesi, cinquantuno uomini.";

var BRIEF_DIALOGO=[{"chi": "A", "t": "Venerdì sei novembre, cinque lavori, nessuna scheda rossa o arancione. Ieri il briefing è saltato perché PubMed non rispondeva; oggi funziona e copre dal tre novembre."}, {"chi": "B", "t": "Richiami, ritrattazioni, consensus?"}, {"chi": "A", "t": "Nessun richiamo nuovo, nessuna ritrattazione che ti riguardi, nessun citante nuovo sui verdetti. La fonte delle linee guida non ha risposto: ho cercato direttamente e c'è solo la definizione Delphi di artrosi refrattaria, nessun consensus sul ginocchio operato."}, {"chi": "B", "t": "Il lavoro del giorno?"}, {"chi": "A", "t": "Fortius Clinic, Londra. Trecentodieci risonanze di centosei calciatori professionisti con crociato leso o ricostruito. Più il ginocchio è piegato durante l'esame, più la tibia sembra ruotata verso l'interno."}, {"chi": "B", "t": "Di quanto?"}, {"chi": "A", "t": "Zero virgola quindici gradi per grado di flessione, intervallo da zero virgola zero due a zero virgola ventisette. Con dieci o venti gradi di differenza si sposta la misura di circa uno virgola cinque o tre gradi."}, {"chi": "B", "t": "E lo slope? Il rinforzo laterale?"}, {"chi": "A", "t": "L'asimmetria di slope pesa molto di più, uno virgola trentatré gradi per grado. Il rinforzo laterale non risulta associato, ma l'abstract non dice in quanti casi era presente, quindi il dato è muto."}, {"chi": "B", "t": "Quindi per la tua pratica?"}, {"chi": "A", "t": "Nessun cambio d'indicazione. Se confronti risonanze nel tempo, registra la flessione dell'esame e guarda l'asimmetria di slope oltre alla pendenza assoluta."}, {"chi": "B", "t": "Gli altri quattro?"}, {"chi": "A", "t": "La monocompartimentale della Mayo: duemiladuecentotrentaquattro ginocchia, novantadue per cento senza revisione a dieci anni, ottantacinque a quindici, ma la tecnologia è soprattutto fluoroscopia. Poi l'osteotomia femorale distale per il valgo, sessantadue ginocchia, ampia variabilità nel singolo. Poi la rassegna sull'allograft per la rotula, senza numeri, e i salti monopodalici dopo il crociato."}];

